// A punch cell with the body driven under it.
// node body.mjs '<cell overrides>' '<drive>'
// drive: { turn, lean (stance, rad / m, in chamber+swing), chamberTorso, swingTorso (thoracic posture),
//          push: [[channel, sense, level?, from?, to?]] (seconds since the swing began; negative = in the chamber) }
import { Vector3 } from "@babylonjs/core/Maths/math.vector.js";
import { punchStand } from "../../punch-calibration.mjs";
import { PLANTED_PUNCH_EXECUTION } from "../../../src/core/skills/combat.ts";
const over = JSON.parse(process.argv[2] ?? "{}"), drive = { turn: 0, lean: 0, push: [], ...JSON.parse(process.argv[3] ?? "{}") };
const s = await punchStand({ hand: "right", family: "straight", hz: 960, seconds: 8, armExtension: .5, ahead: .55, height: 1.55,
  execution: PLANTED_PUNCH_EXECUTION, matchedFeedback: true, paths: { elbowExtension: .5 }, pad: { face: "compliant" }, ...over });
globalThis.__ACTUAL = !!drive.actual;
const inner = s.skills.command;
let swingAt = null, chamberAt = null, last = null;
s.skills.command = (view, intent, dt) => {
  const c = inner(view, intent, dt), phase = s.skills.report.strike.phase;
  if (phase === "chamber" && last !== "chamber") chamberAt = view.time;
  if (phase === "swing" && last !== "swing") swingAt = view.time;
  last = phase;
  if (phase !== "chamber" && phase !== "swing") return c;
  const since = phase === "swing" ? view.time - swingAt : view.time - chamberAt - s.skills.state.hands.right.cycle.time - 1e9;
  const sinceSwing = phase === "swing" ? view.time - swingAt : -(1e-9 + (0.22 - (view.time - chamberAt)));
  let { stance, posture, pushes } = c;
  if (stance && (drive.turn || drive.lean)) {
    const feet = view.stance.soles, mx = (feet.left.x + feet.right.x) / 2, mz = (feet.left.z + feet.right.z) / 2;
    stance = { ...stance, heading: stance.heading + drive.turn, centre: drive.lean ? [mx, mz + drive.lean] : stance.centre };
  }
  const t = phase === "chamber" ? drive.chamberTorso : drive.swingTorso;
  if (t !== undefined) posture = { ...posture, "thoracic rotation right": t };
  const live = drive.push.filter(([, , , from = 0, to = 1]) => sinceSwing >= from && sinceSwing < to);
  if (drive.free && sinceSwing >= drive.free[0] && sinceSwing < drive.free[1]) stance = null;
  if (live.length) pushes = [...pushes, ...live.map(([channel, sense, level = 1]) => ({ channel, sense, level }))];
  void since;
  return { ...c, stance, posture, pushes };
};
const arm = s.built.segments.get("upperArm.right"), v = new Vector3();
let shoulderPeak = 0, fistPeak = 0; const passes = [];
for (let i = 0; i < 8 * 960; i++) {
  s.step();
  if (s.state.phase === "swing" && s.state.witness) { const p = s.state.witness.point, d = Math.hypot(p[0] - s.target[0], p[1] - s.target[1], p[2] - s.target[2]);
    const k = s.state.launch; passes[k] ??= { d: 9 }; if (d < passes[k].d) passes[k] = { d: +d.toFixed(3), off: p.map((x, j) => +(x - s.target[j]).toFixed(3)), v: +s.state.witness.speed.toFixed(2) }; }
  if (s.state.phase === "swing") { arm.body.linearVelocityToRef(v); shoulderPeak = Math.max(shoulderPeak, v.z); fistPeak = Math.max(fistPeak, s.state.witness?.speed ?? 0); }
}
const r = s.reading(); s.dispose();
const clean = r.impacts.filter((e) => e.eligible && e.last10cmSpeed);
const mean = (f) => clean.length ? +(clean.reduce((a, e) => a + f(e), 0) / clean.length).toFixed(3) : null;
console.log(JSON.stringify({ over, drive, n: clean.length, fell: r.fell, faults: r.qualification.faults, speed: mean((e) => e.last10cmSpeed), impulse: mean((e) => e.impulse),
  peak: mean((e) => e.peakStepForce), mass: mean((e) => e.effectiveMass), shoulderPeak: +shoulderPeak.toFixed(2), fistPeak: +fistPeak.toFixed(2),
  raw: r.impacts.map((e) => [e.contacts.join("+"), +e.impulse.toFixed(1), e.truncated]), cycles: r.cycles, passes: passes.filter(Boolean), comp: +r.maximumCompression.toFixed(3) }));

