// node sweep.mjs <out dir> <parallel> <jobs.json: [[cellOverrides, drive], ...]>
import { spawn } from "node:child_process";
import { mkdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
const here = dirname(fileURLToPath(import.meta.url));
const [out, parallel = "10", jobsFile] = process.argv.slice(2);
const jobs = JSON.parse(readFileSync(jobsFile, "utf8"));
mkdirSync(out, { recursive: true });
let next = 0;
const one = (i) => new Promise((done) => {
  const file = resolve(out, `${i}.json`);
  if (existsSync(file)) return done();
  const [cell, drive] = jobs[i];
  const child = spawn(process.execPath, [resolve(here, "body.mjs"), JSON.stringify(cell), JSON.stringify(drive)], { stdio: ["ignore", "pipe", "ignore"] });
  let text = "";
  child.stdout.on("data", (d) => { text += d; });
  child.on("close", () => { const line = text.split("\n").find((l) => l.startsWith("{")); if (line) writeFileSync(file, line); done(); });
});
await Promise.all(Array.from({ length: +parallel }, async () => { while (next < jobs.length) await one(next++); }));
const rows = jobs.map((_, i) => existsSync(resolve(out, `${i}.json`)) ? JSON.parse(readFileSync(resolve(out, `${i}.json`), "utf8")) : null);
for (const [i, r] of rows.entries()) {
  if (!r) { console.log(i, "no output"); continue; }
  console.log(i, JSON.stringify(r.over), JSON.stringify(r.drive), "| n", r.n, "v", r.speed, "J", r.impulse, "F", r.peak?.toFixed?.(0), "m", r.mass, "fist", r.fistPeak, r.faults.join(";"));
}

