// One capacity trial: the combat guard stand, then from t = 2 s the listed channels pushed flat out
// on a schedule, stance released. Scores the right hand's best forward speed at shoulder height.
import { Vector3 } from "@babylonjs/core/Maths/math.vector.js";
import { coreStand } from "../../../tests/harness/core-stand.mjs";
import { modelSpec } from "../../../src/core/models.ts";
import { createBody, SERVO_SECONDS } from "../../../src/core/body.ts";
import { DEFAULT_ENGINE } from "../../../src/core/engine/engines.ts";
import { NO_COVER } from "../../../src/core/mind/intent.ts";
import { combatSkills } from "../../../src/core/skills/combat.ts";

export const CHANNELS = [
  "thoracic rotation right", "lumbar rotation right", "thoracic flexion", "lumbar flexion",
  "hip.left flexion", "hip.left abduction", "hip.left internal rotation", "knee.left flexion", "ankle.left dorsiflexion",
  "hip.right flexion", "hip.right abduction", "hip.right internal rotation", "knee.right flexion", "ankle.right dorsiflexion",
  "shoulder.right flexion", "shoulder.right abduction", "shoulder.right internal rotation", "elbow.right flexion",
];
const T0 = 2, WINDOW = .45;

/** x: per channel [level in -1..1, start s, duration s]. */
export async function trial(x, { hz = 120, keepStance = false, model = "workshop-fighter", trace = false } = {}) {
  const sched = CHANNELS.map((channel, i) => ({ channel, level: x[3 * i], from: x[3 * i + 1], to: x[3 * i + 1] + Math.max(0, x[3 * i + 2]) }))
    .filter((p) => Math.abs(p.level) > .05);
  const s = await coreStand(modelSpec(model), { engine: DEFAULT_ENGINE, hz });
  const body = createBody(s.built, s.world, { servoSeconds: SERVO_SECONDS, feedback: true });
  const skills = combatSkills(body, {});
  body.drive((view, dt) => {
    const c = skills.command(view, { move: null, face: 0, guard: NO_COVER, attack: null }, dt);
    const t = view.time - T0;
    if (t < -.25) return c;
    const live = sched.filter((p) => t >= p.from && t < p.to)
      .map((p) => ({ channel: p.channel, sense: p.level > 0 ? 1 : -1, level: Math.min(1, Math.abs(p.level)) }));
    return { ...c, pushes: [...c.pushes, ...live], ...(keepStance ? {} : { stance: null }) };
  });
  const hand = s.built.segments.get("hand.right"), trunk = s.built.segments.get("upperTrunk"), v = new Vector3();
  let best = 0, at = null, shoulderBest = 0, wristBest = 0, wristAtBest = 0, lastZ = null; const traced = {};
  for (let i = 0; i < (T0 + WINDOW) * hz; i++) {
    s.step();
    const t = s.world.time - T0;
    if (t < -.25) continue;
    hand.body.linearVelocityToRef(v);
    const pos = hand.node.position;
    const wz = lastZ === null ? 0 : (pos.z - lastZ) * hz; lastZ = pos.z;
    const up = trunk.node.position.y > 1.38;
    if (t >= 0 && up && pos.x > (globalThis.__laneLo ?? -9) && pos.x < (globalThis.__laneHi ?? 9) && pos.y > 1.2 && pos.y < 1.6 && pos.z - trunk.node.position.z > .3 && wz > wristBest) wristBest = wz;
