// Diagonal CMA-ES over cap-eval's schedule. node cap-opt.mjs <out.json> <workers> <generations> [opts json]
import { Worker, isMainThread, parentPort, workerData } from "node:worker_threads";
import { writeFileSync, existsSync, readFileSync } from "node:fs";
if (!isMainThread) {
  const { trial } = await import("./cap-eval.mjs"); if (workerData.opts.lane) [globalThis.__laneLo, globalThis.__laneHi] = workerData.opts.lane;
  parentPort.on("message", async ({ id, x }) => {
    let r; try { r = await trial(x, workerData.opts); } catch (e) { r = { score: 0, error: String(e) }; }
    parentPort.postMessage({ id, r });
  });
} else {
  const { CHANNELS } = await import("./cap-eval.mjs");
  const [out, nw = "24", gens = "40", optsJson = "{}"] = process.argv.slice(2);
  const opts = JSON.parse(optsJson), n = CHANNELS.length * 3;
  const lo = [], hi = [];
  for (let i = 0; i < CHANNELS.length; i++) { lo.push(-1, -.3, 0); hi.push(1, .3, .45); }
  const workers = Array.from({ length: +nw }, () => new Worker(new URL(import.meta.url), { workerData: { opts } }));
  let nextId = 0; const waiting = new Map(), idle = [...workers], queue = [];
  for (const w of workers) w.on("message", ({ id, r }) => { waiting.get(id)(r); waiting.delete(id); idle.push(w); pump(); });
  function pump() { while (idle.length && queue.length) { const { id, x } = queue.shift(); idle.pop().postMessage({ id, x }); } }
  const evalx = (x) => new Promise((done) => { const id = nextId++; waiting.set(id, done); queue.push({ id, x }); pump(); });
  // Search in unit space u in [0,1]^n.
  const toX = (u) => u.map((ui, i) => lo[i] + (hi[i] - lo[i]) * Math.min(1, Math.max(0, ui)));
  let m = opts.start ? opts.start.map((x, i) => (x - lo[i]) / (hi[i] - lo[i])) : Array.from({ length: n }, (_, i) => i % 3 === 0 ? .5 : .5);
  let sigma = opts.sigma ?? .25; const C = new Array(n).fill(1);
  const lambda = opts.lambda ?? 4 * +nw, mu = lambda >> 1;
  const wts = Array.from({ length: mu }, (_, i) => Math.log(mu + .5) - Math.log(i + 1)); const ws = wts.reduce((a, b) => a + b); for (let i = 0; i < mu; i++) wts[i] /= ws;
  const mueff = 1 / wts.reduce((a, w) => a + w * w, 0);
  const cs = (mueff + 2) / (n + mueff + 5), ds = 1 + cs, cc = 4 / (n + 4), c1 = 2 / ((n + 1.3) ** 2 + mueff), cmu = Math.min(1 - c1, 2 * (mueff - 2 + 1 / mueff) / ((n + 2) ** 2 + mueff)) * (n + 2) / 3;
  const chiN = Math.sqrt(n) * (1 - 1 / (4 * n) + 1 / (21 * n * n));
  let ps = new Array(n).fill(0), pc = new Array(n).fill(0);
  const gauss = () => { let u = 0, v = 0; while (!u) u = Math.random(); v = Math.random(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
  let best = { score: -1 };
  const log = [];
  for (let g = 0; g < +gens; g++) {
    const zs = Array.from({ length: lambda }, () => Array.from({ length: n }, gauss));
    const us = zs.map((z) => z.map((zi, i) => Math.min(1, Math.max(0, m[i] + sigma * Math.sqrt(C[i]) * zi))));
    const rs = await Promise.all(us.map((u) => evalx(toX(u))));
    const fit = rs.map((r) => r.score - (r.down ? 0 : 0));
    const order = fit.map((f, i) => i).sort((a, b) => fit[b] - fit[a]);
    if (fit[order[0]] > best.score) best = { score: fit[order[0]], x: toX(us[order[0]]), r: rs[order[0]], g };
    const old = m.slice();
    m = m.map((_, i) => order.slice(0, mu).reduce((a, k, j) => a + wts[j] * us[k][i], 0));
    const y = m.map((mi, i) => (mi - old[i]) / sigma);
    ps = ps.map((p, i) => (1 - cs) * p + Math.sqrt(cs * (2 - cs) * mueff) * y[i] / Math.sqrt(C[i]));
    const psn = Math.sqrt(ps.reduce((a, p) => a + p * p, 0));
    pc = pc.map((p, i) => (1 - cc) * p + Math.sqrt(cc * (2 - cc) * mueff) * y[i]);
    for (let i = 0; i < n; i++) {
      let rank = 0; for (let j = 0; j < mu; j++) { const d = (us[order[j]][i] - old[i]) / sigma; rank += wts[j] * d * d; }
      C[i] = (1 - c1 - cmu) * C[i] + c1 * pc[i] * pc[i] + cmu * rank;
    }
    sigma *= Math.exp((cs / ds) * (psn / chiN - 1));
    const med = fit.slice().sort((a, b) => a - b)[lambda >> 1];
    log.push({ g, best: +fit[order[0]].toFixed(3), median: +med.toFixed(3), sigma: +sigma.toFixed(3) });
    console.log(JSON.stringify(log.at(-1)), JSON.stringify(rs[order[0]]));
    writeFileSync(out, JSON.stringify({ opts, best, mean: toX(m), log, channels: CHANNELS }));
  }
  for (const w of workers) w.terminate();
}

