// A punch cell (punchStand) with flat-out pushes added on a schedule counted from each swing's start
// (negative: in the chamber). The stance is kept, so pushes on its bearing legs are its to override.
import { punchStand } from "../../punch-calibration.mjs";
import { PLANTED_PUNCH_EXECUTION } from "../../../src/core/skills/combat.ts";

export const BASE = { hand: "right", family: "cross", hz: 120, seconds: 8, armExtension: .5, ahead: .55, height: 1.55,
  execution: PLANTED_PUNCH_EXECUTION, matchedFeedback: true, paths: { elbowExtension: .5 }, pad: { face: "compliant" } };

/** schedule: [[channel, level -1..1, from s, to s]]. */
export async function cell(over, schedule) {
  const s = await punchStand({ ...BASE, ...over });
  const inner = s.skills.command;
  let swingAt = null, chamberAt = null, last = null;
  const chamberSeconds = s.skills.state.hands?.right?.cycle?.time;
  void chamberSeconds;
  s.skills.command = (view, intent, dt) => {
    const c = inner(view, intent, dt), phase = s.skills.report.strike.phase;
    if (phase === "chamber" && last !== "chamber") chamberAt = view.time;
    if (phase === "swing" && last !== "swing") swingAt = view.time;
    last = phase;
    if (phase !== "chamber" && phase !== "swing") return c;
    // In the chamber, time runs negative toward the swing's planned start.
    const t = phase === "swing" ? view.time - swingAt : (view.time - chamberAt) - (over.paths?.chamberSeconds ?? .22);
    const live = schedule.filter(([, level, from, to]) => Math.abs(level) > .05 && t >= from && t < to)
      .map(([channel, level]) => ({ channel, sense: level > 0 ? 1 : -1, level: Math.min(1, Math.abs(level)) }));
    return live.length ? { ...c, pushes: [...c.pushes, ...live] } : c;
  };
  try {
    s.step(Math.round(s.config.seconds * s.world.hz));
    const r = s.reading();
    const clean = r.impacts.filter((e) => e.eligible && e.last10cmSpeed);
    const mean = (f) => clean.length ? clean.reduce((a, e) => a + f(e), 0) / clean.length : null;
    return { n: clean.length, fell: r.fell, faults: r.qualification.faults, speed: mean((e) => e.last10cmSpeed),
      impulse: mean((e) => e.impulse), peak: mean((e) => e.peakStepForce), mass: mean((e) => e.effectiveMass) };
  } finally { s.dispose(); }
}

